export const componentSource: Record<string, string> = {
  Accordion: "\"use client\";\nimport { useState } from \"react\";\n\nconst DATA = [\n  { title: \"What is React?\", content: \"A JavaScript library for building UIs.\" },\n  { title: \"What is a Hook?\", content: \"A function that lets you use state in function components.\" },\n  { title: \"What is JSX?\", content: \"A syntax extension that lets you write HTML in JS.\" },\n];\n\nexport default function Accordion() {\n  const [openIndex, setOpenIndex] = useState(null);\n\n  const toggle = (index) => {\n    setOpenIndex(openIndex === index ? null : index);\n  };\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Accordion</h2>\n\n      <div className=\"divide-y divide-gray-100 dark:divide-gray-800\">\n        {DATA.map((item, index) => (\n          <div key={item.title}>\n            <button\n              onClick={() => toggle(index)}\n              className=\"w-full flex items-center justify-between py-3 text-left text-sm font-medium\"\n            >\n              {item.title}\n              <span className=\"ml-2 text-gray-400\">\n                {openIndex === index ? \"-\" : \"+\"}\n              </span>\n            </button>\n            {openIndex === index && (\n              <p className=\"pb-3 text-sm text-gray-500 dark:text-gray-400\">\n                {item.content}\n              </p>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  ApiFetch: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nexport default function ApiFetch() {\n  const [users, setUsers] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    fetch(\"https://jsonplaceholder.typicode.com/users\")\n      .then((res) => {\n        if (!res.ok) throw new Error(\"Failed to fetch users\");\n        return res.json();\n      })\n      .then((data) => setUsers(data))\n      .catch((err) => setError(err.message))\n      .finally(() => setLoading(false));\n  }, []);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">API Fetch</h2>\n\n      {loading && (\n        <p className=\"text-center text-sm text-gray-400 animate-pulse\">Loading...</p>\n      )}\n\n      {error && (\n        <p className=\"text-center text-sm text-red-500\">{error}</p>\n      )}\n\n      {!loading && !error && (\n        <ul className=\"divide-y divide-gray-100 dark:divide-gray-800\">\n          {users.map((user) => (\n            <li key={user.id} className=\"py-2 text-sm\">\n              <p className=\"font-medium text-gray-800 dark:text-gray-100\">{user.name}</p>\n              <p className=\"text-gray-400 text-xs\">{user.email}</p>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  );\n}\n",
  Autocomplete: "\"use client\";\nimport { useState, useRef, useEffect } from \"react\";\n\nconst FRUITS = [\n  \"Apple\", \"Apricot\", \"Banana\", \"Blueberry\", \"Cherry\",\n  \"Grape\", \"Guava\", \"Kiwi\", \"Lychee\", \"Mango\",\n  \"Orange\", \"Papaya\", \"Pineapple\", \"Strawberry\", \"Watermelon\",\n];\n\nexport default function Autocomplete() {\n  const [query, setQuery] = useState(\"\");\n  const [isOpen, setIsOpen] = useState(false);\n  const [activeIndex, setActiveIndex] = useState(-1);\n  const wrapperRef = useRef(null);\n\n  const suggestions =\n    query.trim() === \"\"\n      ? []\n      : FRUITS.filter((fruit) =>\n          fruit.toLowerCase().includes(query.toLowerCase())\n        );\n\n  // close the dropdown when clicking outside\n  useEffect(() => {\n    const handleClickOutside = (e) => {\n      if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {\n        setIsOpen(false);\n      }\n    };\n    document.addEventListener(\"mousedown\", handleClickOutside);\n    return () => document.removeEventListener(\"mousedown\", handleClickOutside);\n  }, []);\n\n  const selectSuggestion = (value) => {\n    setQuery(value);\n    setIsOpen(false);\n    setActiveIndex(-1);\n  };\n\n  const handleKeyDown = (e) => {\n    if (!isOpen || suggestions.length === 0) return;\n\n    if (e.key === \"ArrowDown\") {\n      e.preventDefault();\n      setActiveIndex((prev) => (prev + 1) % suggestions.length);\n    } else if (e.key === \"ArrowUp\") {\n      e.preventDefault();\n      setActiveIndex((prev) => (prev <= 0 ? suggestions.length - 1 : prev - 1));\n    } else if (e.key === \"Enter\" && activeIndex >= 0) {\n      selectSuggestion(suggestions[activeIndex]);\n    } else if (e.key === \"Escape\") {\n      setIsOpen(false);\n    }\n  };\n\n  return (\n    <div\n      ref={wrapperRef}\n      className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700 relative\"\n    >\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Autocomplete</h2>\n\n      <input\n        value={query}\n        onChange={(e) => {\n          setQuery(e.target.value);\n          setIsOpen(true);\n          setActiveIndex(-1);\n        }}\n        onFocus={() => setIsOpen(true)}\n        onKeyDown={handleKeyDown}\n        placeholder=\"Search a fruit...\"\n        className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n      />\n\n      {isOpen && suggestions.length > 0 && (\n        <ul className=\"absolute left-6 right-6 mt-1 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg max-h-48 overflow-y-auto z-10\">\n          {suggestions.map((fruit, index) => (\n            <li\n              key={fruit}\n              onMouseDown={() => selectSuggestion(fruit)}\n              className={`px-3 py-2 text-sm cursor-pointer ${\n                index === activeIndex\n                  ? \"bg-blue-600 text-white\"\n                  : \"hover:bg-gray-100 dark:hover:bg-gray-800\"\n              }`}\n            >\n              {fruit}\n            </li>\n          ))}\n        </ul>\n      )}\n\n      {isOpen && query.trim() !== \"\" && suggestions.length === 0 && (\n        <p className=\"absolute left-6 right-6 mt-1 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg px-3 py-2 text-sm text-gray-400 z-10\">\n          No matches found\n        </p>\n      )}\n    </div>\n  );\n}\n",
  Carousel: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nconst SLIDES = [\n  { id: 1, color: \"bg-red-500\", text: \"Slide 1\" },\n  { id: 2, color: \"bg-blue-500\", text: \"Slide 2\" },\n  { id: 3, color: \"bg-green-500\", text: \"Slide 3\" },\n];\n\nexport default function Carousel() {\n  const [index, setIndex] = useState(0);\n\n  const prevSlide = () => {\n    setIndex((prev) => (prev === 0 ? SLIDES.length - 1 : prev - 1));\n  };\n\n  const nextSlide = () => {\n    setIndex((prev) => (prev === SLIDES.length - 1 ? 0 : prev + 1));\n  };\n\n  // auto-play every 3 seconds\n  useEffect(() => {\n    const timer = setInterval(nextSlide, 3000);\n    return () => clearInterval(timer);\n  }, []);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Carousel</h2>\n\n      <div\n        className={`h-36 rounded-md flex items-center justify-center text-white text-xl font-medium transition-colors ${SLIDES[index].color}`}\n      >\n        {SLIDES[index].text}\n      </div>\n\n      <div className=\"flex items-center justify-center gap-2 mt-4\">\n        <button\n          onClick={prevSlide}\n          className=\"px-3 py-1.5 rounded-md border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Prev\n        </button>\n        <button\n          onClick={nextSlide}\n          className=\"px-3 py-1.5 rounded-md border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Next\n        </button>\n      </div>\n\n      <div className=\"flex items-center justify-center gap-2 mt-3\">\n        {SLIDES.map((slide, i) => (\n          <button\n            key={slide.id}\n            onClick={() => setIndex(i)}\n            className={`h-2.5 w-2.5 rounded-full transition-colors ${\n              i === index ? \"bg-gray-800 dark:bg-gray-200\" : \"bg-gray-300 dark:bg-gray-600\"\n            }`}\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  Counter: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nexport default function Counter() {\n  const [count, setCount] = useState(0);\n\n  // keep the tab title in sync with the count\n  useEffect(() => {\n    document.title = `Count: ${count}`;\n    return () => {\n      document.title = \"my-next-app\";\n    };\n  }, [count]);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Counter</h2>\n      <p className=\"text-4xl font-bold mb-6\">{count}</p>\n      <div className=\"flex items-center justify-center gap-2\">\n        <button\n          onClick={() => setCount((c) => c - 1)}\n          className=\"h-9 w-9 rounded-md border border-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          -\n        </button>\n        <button\n          onClick={() => setCount(0)}\n          className=\"px-3 h-9 rounded-md border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Reset\n        </button>\n        <button\n          onClick={() => setCount((c) => c + 1)}\n          className=\"h-9 w-9 rounded-md border border-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          +\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  DarkModeToggle: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nexport default function DarkModeToggle() {\n  const [isDark, setIsDark] = useState(false);\n\n  // read saved preference (or system preference) once on mount\n  useEffect(() => {\n    const saved = localStorage.getItem(\"theme\");\n    const prefersDark = window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n    setIsDark(saved ? saved === \"dark\" : prefersDark);\n  }, []);\n\n  // apply the class + persist whenever the theme changes\n  useEffect(() => {\n    document.documentElement.classList.toggle(\"dark\", isDark);\n    localStorage.setItem(\"theme\", isDark ? \"dark\" : \"light\");\n  }, [isDark]);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Dark Mode Toggle</h2>\n\n      <button\n        onClick={() => setIsDark((prev) => !prev)}\n        className=\"px-4 py-2 rounded-full border border-gray-300 text-sm flex items-center gap-2 mx-auto hover:bg-gray-100 dark:hover:bg-gray-800\"\n      >\n        <span>{isDark ? \"🌙\" : \"☀️\"}</span>\n        {isDark ? \"Dark Mode\" : \"Light Mode\"}\n      </button>\n    </div>\n  );\n}\n",
  DataTable: "\"use client\";\nimport { useState } from \"react\";\n\nconst USERS = [\n  { id: 1, name: \"Amit Sharma\", role: \"Frontend Dev\", experience: 3 },\n  { id: 2, name: \"Priya Verma\", role: \"Backend Dev\", experience: 5 },\n  { id: 3, name: \"Rahul Singh\", role: \"Full Stack Dev\", experience: 2 },\n  { id: 4, name: \"Sneha Gupta\", role: \"UI/UX Designer\", experience: 4 },\n  { id: 5, name: \"Vikram Rao\", role: \"DevOps Engineer\", experience: 6 },\n];\n\nexport default function DataTable() {\n  const [filterText, setFilterText] = useState(\"\");\n  const [sortConfig, setSortConfig] = useState({ key: \"name\", direction: \"asc\" });\n\n  const handleSort = (key) => {\n    setSortConfig((prev) => ({\n      key,\n      direction: prev.key === key && prev.direction === \"asc\" ? \"desc\" : \"asc\",\n    }));\n  };\n\n  const filtered = USERS.filter((user) =>\n    user.name.toLowerCase().includes(filterText.toLowerCase())\n  );\n\n  const sorted = [...filtered].sort((a, b) => {\n    const { key, direction } = sortConfig;\n    const factor = direction === \"asc\" ? 1 : -1;\n    if (a[key] < b[key]) return -1 * factor;\n    if (a[key] > b[key]) return 1 * factor;\n    return 0;\n  });\n\n  const columns = [\n    { key: \"name\", label: \"Name\" },\n    { key: \"role\", label: \"Role\" },\n    { key: \"experience\", label: \"Exp (yrs)\" },\n  ];\n\n  return (\n    <div className=\"max-w-lg mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Data Table</h2>\n\n      <input\n        value={filterText}\n        onChange={(e) => setFilterText(e.target.value)}\n        placeholder=\"Filter by name...\"\n        className=\"w-full mb-4 rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n      />\n\n      <div className=\"overflow-x-auto\">\n        <table className=\"w-full text-sm text-left\">\n          <thead>\n            <tr className=\"border-b border-gray-200 dark:border-gray-700\">\n              {columns.map((col) => (\n                <th\n                  key={col.key}\n                  onClick={() => handleSort(col.key)}\n                  className=\"py-2 px-2 cursor-pointer select-none font-medium text-gray-600 dark:text-gray-300\"\n                >\n                  {col.label}\n                  {sortConfig.key === col.key && (\n                    <span className=\"ml-1\">\n                      {sortConfig.direction === \"asc\" ? \"▲\" : \"▼\"}\n                    </span>\n                  )}\n                </th>\n              ))}\n            </tr>\n          </thead>\n          <tbody className=\"divide-y divide-gray-100 dark:divide-gray-800\">\n            {sorted.length === 0 ? (\n              <tr>\n                <td colSpan={columns.length} className=\"py-6 text-center text-gray-400\">\n                  No matching rows\n                </td>\n              </tr>\n            ) : (\n              sorted.map((user) => (\n                <tr key={user.id}>\n                  <td className=\"py-2 px-2\">{user.name}</td>\n                  <td className=\"py-2 px-2 text-gray-500 dark:text-gray-400\">{user.role}</td>\n                  <td className=\"py-2 px-2 text-gray-500 dark:text-gray-400\">{user.experience}</td>\n                </tr>\n              ))\n            )}\n          </tbody>\n        </table>\n      </div>\n    </div>\n  );\n}\n",
  DebounceSearch: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nconst NAMES = [\"Amit\", \"Priya\", \"Rahul\", \"Sneha\", \"Vikram\", \"Anjali\", \"Rohit\", \"Neha\"];\n\nexport default function DebounceSearch() {\n  const [query, setQuery] = useState(\"\");\n  const [debouncedQuery, setDebouncedQuery] = useState(\"\");\n\n  // debounce: wait 500ms after the user stops typing before updating debouncedQuery\n  useEffect(() => {\n    const timer = setTimeout(() => {\n      setDebouncedQuery(query);\n    }, 500);\n\n    return () => clearTimeout(timer);\n  }, [query]);\n\n  const filtered = NAMES.filter((name) =>\n    name.toLowerCase().includes(debouncedQuery.toLowerCase())\n  );\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Debounce Search</h2>\n\n      <input\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Type to search...\"\n        className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n      />\n\n      <p className=\"mt-2 text-xs text-gray-400\">\n        Searching for: {debouncedQuery || \"(nothing yet)\"}\n      </p>\n\n      <ul className=\"mt-2 divide-y divide-gray-100 dark:divide-gray-800\">\n        {filtered.map((name) => (\n          <li key={name} className=\"py-2 text-sm text-gray-700 dark:text-gray-200\">\n            {name}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
  DragDropList: "\"use client\";\nimport { useState, useRef } from \"react\";\n\nexport default function DragDropList() {\n  const [items, setItems] = useState([\"Learn JS\", \"Learn React\", \"Learn Next.js\", \"Build Projects\", \"Apply for Jobs\"]);\n  const dragIndex = useRef(null);\n  const [overIndex, setOverIndex] = useState(null);\n\n  const handleDragStart = (index) => {\n    dragIndex.current = index;\n  };\n\n  const handleDragOver = (e, index) => {\n    e.preventDefault();\n    setOverIndex(index);\n  };\n\n  const handleDrop = (index) => {\n    const from = dragIndex.current;\n    if (from === null || from === index) return;\n\n    const updated = [...items];\n    const [moved] = updated.splice(from, 1);\n    updated.splice(index, 0, moved);\n\n    setItems(updated);\n    dragIndex.current = null;\n    setOverIndex(null);\n  };\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Drag & Drop List</h2>\n\n      <ul className=\"space-y-2\">\n        {items.map((item, index) => (\n          <li\n            key={item}\n            draggable\n            onDragStart={() => handleDragStart(index)}\n            onDragOver={(e) => handleDragOver(e, index)}\n            onDrop={() => handleDrop(index)}\n            onDragEnd={() => setOverIndex(null)}\n            className={`px-3 py-2 rounded-md border text-sm cursor-move select-none transition-colors ${\n              overIndex === index\n                ? \"border-blue-500 bg-blue-50 dark:bg-blue-950\"\n                : \"border-gray-200 dark:border-gray-700\"\n            }`}\n          >\n            {item}\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
  FileExplorer: "\"use client\";\nimport { useState } from \"react\";\n\nconst DEFAULT_TREE = {\n  name: \"src\",\n  type: \"folder\",\n  children: [\n    {\n      name: \"components\",\n      type: \"folder\",\n      children: [\n        { name: \"Header.jsx\", type: \"file\" },\n        { name: \"Footer.jsx\", type: \"file\" },\n        {\n          name: \"ui\",\n          type: \"folder\",\n          children: [{ name: \"Button.jsx\", type: \"file\" }],\n        },\n      ],\n    },\n    {\n      name: \"pages\",\n      type: \"folder\",\n      children: [\n        { name: \"index.jsx\", type: \"file\" },\n        { name: \"about.jsx\", type: \"file\" },\n      ],\n    },\n    { name: \"App.jsx\", type: \"file\" },\n    { name: \"index.js\", type: \"file\" },\n  ],\n};\n\n// Recursive: a folder node just renders more <Node> for each child, so this\n// handles arbitrary depth for free — no special-casing per level.\nfunction Node({ node }) {\n  const [isOpen, setIsOpen] = useState(false);\n\n  if (node.type === \"file\") {\n    return <div className=\"pl-5 py-1 text-sm text-gray-600 dark:text-gray-300\">📄 {node.name}</div>;\n  }\n\n  const toggle = () => setIsOpen((prev) => !prev);\n\n  return (\n    <div>\n      <div\n        role=\"button\"\n        tabIndex={0}\n        onClick={toggle}\n        onKeyDown={(e) => (e.key === \"Enter\" || e.key === \" \") && (e.preventDefault(), toggle())}\n        className=\"py-1 text-sm font-medium cursor-pointer select-none\"\n      >\n        {isOpen ? \"📂\" : \"📁\"} {node.name}\n      </div>\n      {isOpen && (\n        <div className=\"pl-4 border-l border-gray-200 dark:border-gray-700 ml-1\">\n          {node.children.map((child, index) => (\n            <Node key={`${child.name}-${index}`} node={child} />\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n\n// Reusable: pass any { name, type, children } tree via `data`; falls back to a demo tree.\nexport default function FileExplorer({ data = DEFAULT_TREE }) {\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">File Explorer</h2>\n      <Node node={data} />\n    </div>\n  );\n}\n",
  FormValidation: "\"use client\";\nimport { useState } from \"react\";\n\nexport default function FormValidation() {\n  const [values, setValues] = useState({ name: \"\", email: \"\", password: \"\" });\n  const [errors, setErrors] = useState({});\n  const [submitted, setSubmitted] = useState(false);\n\n  const handleChange = (e) => {\n    setValues({ ...values, [e.target.name]: e.target.value });\n  };\n\n  const validate = () => {\n    const newErrors = {};\n\n    if (!values.name.trim()) newErrors.name = \"Name is required\";\n\n    if (!values.email.trim()) {\n      newErrors.email = \"Email is required\";\n    } else if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(values.email)) {\n      newErrors.email = \"Email is invalid\";\n    }\n\n    if (!values.password) {\n      newErrors.password = \"Password is required\";\n    } else if (values.password.length < 6) {\n      newErrors.password = \"Password must be at least 6 characters\";\n    }\n\n    return newErrors;\n  };\n\n  const handleSubmit = (e) => {\n    e.preventDefault();\n    const newErrors = validate();\n    setErrors(newErrors);\n    setSubmitted(Object.keys(newErrors).length === 0);\n  };\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Form Validation</h2>\n\n      <form onSubmit={handleSubmit} className=\"space-y-3\" noValidate>\n        <div>\n          <input\n            name=\"name\"\n            value={values.name}\n            onChange={handleChange}\n            placeholder=\"Name\"\n            className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n          />\n          {errors.name && <p className=\"text-xs text-red-500 mt-1\">{errors.name}</p>}\n        </div>\n\n        <div>\n          <input\n            name=\"email\"\n            value={values.email}\n            onChange={handleChange}\n            placeholder=\"Email\"\n            className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n          />\n          {errors.email && <p className=\"text-xs text-red-500 mt-1\">{errors.email}</p>}\n        </div>\n\n        <div>\n          <input\n            type=\"password\"\n            name=\"password\"\n            value={values.password}\n            onChange={handleChange}\n            placeholder=\"Password\"\n            className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n          />\n          {errors.password && <p className=\"text-xs text-red-500 mt-1\">{errors.password}</p>}\n        </div>\n\n        <button\n          type=\"submit\"\n          className=\"w-full py-2 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n        >\n          Submit\n        </button>\n\n        {submitted && (\n          <p className=\"text-sm text-green-600 text-center\">Form submitted successfully!</p>\n        )}\n      </form>\n    </div>\n  );\n}\n",
  InfiniteScroll: "\"use client\";\nimport { useState, useEffect, useRef, useCallback } from \"react\";\n\nexport default function InfiniteScroll() {\n  const [items, setItems] = useState(() =>\n    Array.from({ length: 20 }, (_, i) => `Item ${i + 1}`)\n  );\n  const [loading, setLoading] = useState(false);\n  const loaderRef = useRef(null);\n\n  const loadMore = useCallback(() => {\n    setLoading(true);\n    // simulate an API call\n    setTimeout(() => {\n      setItems((prev) => [\n        ...prev,\n        ...Array.from({ length: 10 }, (_, i) => `Item ${prev.length + i + 1}`),\n      ]);\n      setLoading(false);\n    }, 800);\n  }, []);\n\n  useEffect(() => {\n    const observer = new IntersectionObserver(\n      (entries) => {\n        if (entries[0].isIntersecting && !loading) {\n          loadMore();\n        }\n      },\n      { threshold: 1 }\n    );\n\n    if (loaderRef.current) observer.observe(loaderRef.current);\n    return () => observer.disconnect();\n  }, [loadMore, loading]);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700 overflow-hidden\">\n      <h2 className=\"text-xl font-semibold p-4 text-center border-b border-gray-200 dark:border-gray-700\">\n        Infinite Scroll\n      </h2>\n\n      <ul className=\"h-72 overflow-y-auto divide-y divide-gray-100 dark:divide-gray-800\">\n        {items.map((item) => (\n          <li key={item} className=\"px-4 py-2 text-sm text-gray-700 dark:text-gray-200\">\n            {item}\n          </li>\n        ))}\n        <li ref={loaderRef} className=\"py-4 text-center text-xs text-gray-400\">\n          {loading ? \"Loading more...\" : \"Scroll down for more\"}\n        </li>\n      </ul>\n    </div>\n  );\n}\n",
  KanbanBoard: "\"use client\";\nimport { useState, useRef } from \"react\";\n\nconst INITIAL_COLUMNS = {\n  todo: { title: \"To Do\", tasks: [{ id: \"t1\", text: \"Design login page\" }, { id: \"t2\", text: \"Set up CI pipeline\" }] },\n  inProgress: { title: \"In Progress\", tasks: [{ id: \"t3\", text: \"Build auth API\" }] },\n  done: { title: \"Done\", tasks: [{ id: \"t4\", text: \"Project setup\" }] },\n};\n\nexport default function KanbanBoard() {\n  const [columns, setColumns] = useState(INITIAL_COLUMNS);\n  const [newTask, setNewTask] = useState(\"\");\n  const [overCol, setOverCol] = useState(null);\n  const dragInfo = useRef(null); // { taskId, fromCol }\n\n  const addTask = () => {\n    if (!newTask.trim()) return;\n    setColumns((prev) => ({\n      ...prev,\n      todo: { ...prev.todo, tasks: [...prev.todo.tasks, { id: `t${Date.now()}`, text: newTask }] },\n    }));\n    setNewTask(\"\");\n  };\n\n  const handleDrop = (toCol) => {\n    const info = dragInfo.current;\n    setOverCol(null);\n    if (!info || info.fromCol === toCol) return;\n\n    setColumns((prev) => {\n      const fromTasks = prev[info.fromCol].tasks;\n      const task = fromTasks.find((t) => t.id === info.taskId);\n      if (!task) return prev;\n\n      return {\n        ...prev,\n        [info.fromCol]: { ...prev[info.fromCol], tasks: fromTasks.filter((t) => t.id !== info.taskId) },\n        [toCol]: { ...prev[toCol], tasks: [...prev[toCol].tasks, task] },\n      };\n    });\n    dragInfo.current = null;\n  };\n\n  return (\n    <div className=\"max-w-3xl mx-auto mt-8 p-4\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Kanban Board</h2>\n\n      <div className=\"flex gap-2 mb-4 max-w-sm mx-auto\">\n        <input\n          value={newTask}\n          onChange={(e) => setNewTask(e.target.value)}\n          onKeyDown={(e) => e.key === \"Enter\" && addTask()}\n          placeholder=\"New task -> To Do\"\n          className=\"flex-1 rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n        />\n        <button\n          onClick={addTask}\n          className=\"px-3 py-1.5 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n        >\n          Add\n        </button>\n      </div>\n\n      <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n        {Object.entries(columns).map(([colKey, col]) => (\n          <div\n            key={colKey}\n            onDragOver={(e) => {\n              e.preventDefault();\n              setOverCol(colKey);\n            }}\n            onDragLeave={() => setOverCol((c) => (c === colKey ? null : c))}\n            onDrop={() => handleDrop(colKey)}\n            className={`rounded-lg border p-3 min-h-[220px] transition-colors ${\n              overCol === colKey\n                ? \"border-blue-500 bg-blue-50 dark:bg-blue-950\"\n                : \"border-gray-200 dark:border-gray-700\"\n            }`}\n          >\n            <h3 className=\"text-sm font-semibold mb-2 text-gray-600 dark:text-gray-300\">\n              {col.title} <span className=\"text-gray-400\">({col.tasks.length})</span>\n            </h3>\n\n            <ul className=\"space-y-2\">\n              {col.tasks.map((task) => (\n                <li\n                  key={task.id}\n                  draggable\n                  onDragStart={() => {\n                    dragInfo.current = { taskId: task.id, fromCol: colKey };\n                  }}\n                  className=\"px-3 py-2 rounded-md border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm cursor-move select-none shadow-sm\"\n                >\n                  {task.text}\n                </li>\n              ))}\n              {col.tasks.length === 0 && (\n                <li className=\"text-xs text-gray-400 text-center py-4\">Drop tasks here</li>\n              )}\n            </ul>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  Loader: "\"use client\";\nexport default function Loader() {\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Loader</h2>\n      <div className=\"h-10 w-10 mx-auto rounded-full border-4 border-gray-200 border-t-blue-600 animate-spin dark:border-gray-700 dark:border-t-blue-500\" />\n    </div>\n  );\n}\n",
  Modal: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nexport default function Modal() {\n  const [isOpen, setIsOpen] = useState(false);\n\n  // close on Escape key\n  useEffect(() => {\n    if (!isOpen) return;\n\n    const handleKeyDown = (e) => {\n      if (e.key === \"Escape\") setIsOpen(false);\n    };\n    window.addEventListener(\"keydown\", handleKeyDown);\n\n    // lock body scroll while modal is open\n    document.body.style.overflow = \"hidden\";\n\n    return () => {\n      window.removeEventListener(\"keydown\", handleKeyDown);\n      document.body.style.overflow = \"\";\n    };\n  }, [isOpen]);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Modal</h2>\n      <button\n        onClick={() => setIsOpen(true)}\n        className=\"px-4 py-2 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n      >\n        Open Modal\n      </button>\n\n      {isOpen && (\n        <div\n          onClick={() => setIsOpen(false)}\n          className=\"fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50\"\n        >\n          <div\n            onClick={(e) => e.stopPropagation()}\n            className=\"bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 rounded-lg p-6 w-full max-w-sm shadow-lg\"\n          >\n            <h3 className=\"text-lg font-semibold mb-2\">I am a Modal</h3>\n            <p className=\"text-sm text-gray-500 dark:text-gray-400 mb-4\">\n              Click outside, press Esc, or use the button below to close.\n            </p>\n            <button\n              onClick={() => setIsOpen(false)}\n              className=\"px-3 py-1.5 rounded-md border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n            >\n              Close\n            </button>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n",
  NestedComments: "\"use client\";\nimport { useState } from \"react\";\n\nconst INITIAL_COMMENTS = [\n  {\n    id: \"1\",\n    author: \"Amit\",\n    text: \"Great write-up on recursion!\",\n    replies: [\n      {\n        id: \"1-1\",\n        author: \"Priya\",\n        text: \"Agreed, the diagrams helped a lot.\",\n        replies: [],\n      },\n    ],\n  },\n  {\n    id: \"2\",\n    author: \"Rahul\",\n    text: \"Can you cover memoization next?\",\n    replies: [],\n  },\n];\n\nfunction addReply(comments, parentId, reply) {\n  return comments.map((comment) => {\n    if (comment.id === parentId) {\n      return { ...comment, replies: [...comment.replies, reply] };\n    }\n    return { ...comment, replies: addReply(comment.replies, parentId, reply) };\n  });\n}\n\n// Recursive: each comment renders its own replies as more <Comment> nodes,\n// so a thread can nest arbitrarily deep with no extra logic per level.\nfunction Comment({ comment, onReply, depth }) {\n  const [showReplyBox, setShowReplyBox] = useState(false);\n  const [replyText, setReplyText] = useState(\"\");\n  const [collapsed, setCollapsed] = useState(false);\n  const hasReplies = comment.replies.length > 0;\n\n  const submitReply = () => {\n    if (!replyText.trim()) return;\n    onReply(comment.id, replyText);\n    setReplyText(\"\");\n    setShowReplyBox(false);\n  };\n\n  return (\n    <li className=\"mt-3\">\n      <div className=\"flex items-start gap-2\">\n        {hasReplies && (\n          <button\n            onClick={() => setCollapsed((c) => !c)}\n            className=\"mt-0.5 text-xs text-gray-400 hover:text-gray-600 w-4\"\n            aria-label={collapsed ? \"Expand replies\" : \"Collapse replies\"}\n          >\n            {collapsed ? \"+\" : \"−\"}\n          </button>\n        )}\n        <div className=\"flex-1\">\n          <p className=\"text-sm\">\n            <span className=\"font-medium text-gray-800 dark:text-gray-100\">{comment.author}</span>{\" \"}\n            <span className=\"text-gray-600 dark:text-gray-300\">{comment.text}</span>\n          </p>\n          <button\n            onClick={() => setShowReplyBox((s) => !s)}\n            className=\"mt-1 text-xs text-blue-600 hover:underline\"\n          >\n            Reply\n          </button>\n\n          {showReplyBox && (\n            <div className=\"mt-2 flex gap-2\">\n              <input\n                autoFocus\n                value={replyText}\n                onChange={(e) => setReplyText(e.target.value)}\n                onKeyDown={(e) => e.key === \"Enter\" && submitReply()}\n                placeholder={`Reply to ${comment.author}...`}\n                className=\"flex-1 rounded-md border border-gray-300 px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n              />\n              <button\n                onClick={submitReply}\n                className=\"px-2 py-1 rounded-md bg-blue-600 text-white text-xs hover:bg-blue-700\"\n              >\n                Post\n              </button>\n            </div>\n          )}\n\n          {!collapsed && hasReplies && (\n            <ul className=\"pl-4 border-l border-gray-200 dark:border-gray-700\">\n              {comment.replies.map((reply) => (\n                <Comment key={reply.id} comment={reply} onReply={onReply} depth={depth + 1} />\n              ))}\n            </ul>\n          )}\n        </div>\n      </div>\n    </li>\n  );\n}\n\nexport default function NestedComments() {\n  const [comments, setComments] = useState(INITIAL_COMMENTS);\n  const [newComment, setNewComment] = useState(\"\");\n\n  const handleReply = (parentId, text) => {\n    const reply = { id: `${parentId}-${Date.now()}`, author: \"You\", text, replies: [] };\n    setComments((prev) => addReply(prev, parentId, reply));\n  };\n\n  const addTopLevelComment = () => {\n    if (!newComment.trim()) return;\n    setComments((prev) => [\n      ...prev,\n      { id: String(Date.now()), author: \"You\", text: newComment, replies: [] },\n    ]);\n    setNewComment(\"\");\n  };\n\n  return (\n    <div className=\"max-w-md mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Nested Comments</h2>\n\n      <div className=\"flex gap-2\">\n        <input\n          value={newComment}\n          onChange={(e) => setNewComment(e.target.value)}\n          onKeyDown={(e) => e.key === \"Enter\" && addTopLevelComment()}\n          placeholder=\"Add a comment...\"\n          className=\"flex-1 rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n        />\n        <button\n          onClick={addTopLevelComment}\n          className=\"px-3 py-1.5 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n        >\n          Post\n        </button>\n      </div>\n\n      <ul className=\"mt-2\">\n        {comments.map((comment) => (\n          <Comment key={comment.id} comment={comment} onReply={handleReply} depth={0} />\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
  OtpInput: "\"use client\";\nimport { useState, useRef, useEffect } from \"react\";\n\nconst LENGTH = 4;\n\nexport default function OtpInput() {\n  const [otp, setOtp] = useState(Array(LENGTH).fill(\"\"));\n  const inputRefs = useRef([]);\n\n  // focus the first box on mount\n  useEffect(() => {\n    inputRefs.current[0]?.focus();\n  }, []);\n\n  const handleChange = (e, index) => {\n    const value = e.target.value.replace(/[^0-9]/g, \"\").slice(-1);\n    const updated = [...otp];\n    updated[index] = value;\n    setOtp(updated);\n\n    if (value && index < LENGTH - 1) {\n      inputRefs.current[index + 1]?.focus();\n    }\n  };\n\n  const handleKeyDown = (e, index) => {\n    if (e.key === \"Backspace\" && !otp[index] && index > 0) {\n      inputRefs.current[index - 1]?.focus();\n    }\n  };\n\n  const handlePaste = (e) => {\n    e.preventDefault();\n    const pasted = e.clipboardData.getData(\"text\").replace(/[^0-9]/g, \"\").slice(0, LENGTH);\n    const updated = pasted.split(\"\");\n    setOtp([...updated, ...Array(LENGTH - updated.length).fill(\"\")]);\n    inputRefs.current[Math.min(updated.length, LENGTH - 1)]?.focus();\n  };\n\n  const isComplete = otp.every((digit) => digit !== \"\");\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">OTP Input</h2>\n\n      <div className=\"flex items-center justify-center gap-2\">\n        {otp.map((digit, index) => (\n          <input\n            key={index}\n            ref={(el) => (inputRefs.current[index] = el)}\n            value={digit}\n            onChange={(e) => handleChange(e, index)}\n            onKeyDown={(e) => handleKeyDown(e, index)}\n            onPaste={handlePaste}\n            maxLength={1}\n            inputMode=\"numeric\"\n            className=\"h-12 w-12 text-center text-lg rounded-md border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n          />\n        ))}\n      </div>\n\n      <p className=\"mt-4 text-sm text-gray-500 dark:text-gray-400\">\n        {isComplete ? `Entered OTP: ${otp.join(\"\")}` : \"Enter the 4-digit code\"}\n      </p>\n    </div>\n  );\n}\n",
  Pagination: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nconst ITEMS = Array.from({ length: 47 }, (_, i) => `Item ${i + 1}`);\nconst PAGE_SIZE = 5;\n\nexport default function Pagination() {\n  const [page, setPage] = useState(1);\n  const [loading, setLoading] = useState(false);\n  const [currentItems, setCurrentItems] = useState([]);\n\n  const totalPages = Math.ceil(ITEMS.length / PAGE_SIZE);\n\n  // simulate fetching a fresh page of data whenever the page changes\n  useEffect(() => {\n    setLoading(true);\n\n    const timer = setTimeout(() => {\n      const start = (page - 1) * PAGE_SIZE;\n      setCurrentItems(ITEMS.slice(start, start + PAGE_SIZE));\n      setLoading(false);\n    }, 300);\n\n    return () => clearTimeout(timer);\n  }, [page]);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-4 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Pagination</h2>\n\n      <ul className=\"min-h-[180px] divide-y divide-gray-100 dark:divide-gray-800\">\n        {loading ? (\n          <li className=\"py-8 text-center text-gray-400 animate-pulse\">\n            Loading...\n          </li>\n        ) : (\n          currentItems.map((item) => (\n            <li\n              key={item}\n              className=\"py-2 px-3 text-gray-700 dark:text-gray-200\"\n            >\n              {item}\n            </li>\n          ))\n        )}\n      </ul>\n\n      <div className=\"flex items-center justify-center flex-wrap gap-2 mt-4\">\n        <button\n          disabled={page === 1}\n          onClick={() => setPage((p) => p - 1)}\n          className=\"px-3 py-1 rounded-md text-sm border border-gray-300 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Prev\n        </button>\n\n        {Array.from({ length: totalPages }, (_, i) => i + 1).map((num) => (\n          <button\n            key={num}\n            onClick={() => setPage(num)}\n            className={`h-8 w-8 rounded-md text-sm border transition-colors ${\n              num === page\n                ? \"bg-blue-600 text-white border-blue-600\"\n                : \"border-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800\"\n            }`}\n          >\n            {num}\n          </button>\n        ))}\n\n        <button\n          disabled={page === totalPages}\n          onClick={() => setPage((p) => p + 1)}\n          className=\"px-3 py-1 rounded-md text-sm border border-gray-300 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Next\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  ProductPagination: "\"use client\";\nimport { useState, useEffect } from \"react\";\n\nconst PAGE_SIZE = 6;\nconst API_URL = \"https://dummyjson.com/products\";\n\nexport default function ProductPagination() {\n  const [page, setPage] = useState(1);\n  const [reloadToken, setReloadToken] = useState(0); // bump to force a refetch of the same page\n  const [products, setProducts] = useState([]);\n  const [total, setTotal] = useState(0);\n  const [status, setStatus] = useState(\"idle\"); // idle | loading | success | error\n  const [errorMsg, setErrorMsg] = useState(\"\");\n\n  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));\n\n  useEffect(() => {\n    const controller = new AbortController();\n    const skip = (page - 1) * PAGE_SIZE;\n\n    setStatus(\"loading\");\n    setErrorMsg(\"\");\n\n    fetch(`${API_URL}?limit=${PAGE_SIZE}&skip=${skip}`, { signal: controller.signal })\n      .then((res) => {\n        if (!res.ok) throw new Error(`Request failed with status ${res.status}`);\n        return res.json();\n      })\n      .then((data) => {\n        setProducts(data.products || []);\n        setTotal(data.total || 0);\n        setStatus(\"success\");\n      })\n      .catch((err) => {\n        if (err.name === \"AbortError\") return; // page changed again before this settled\n        setStatus(\"error\");\n        setErrorMsg(err.message || \"Something went wrong\");\n      });\n\n    return () => controller.abort();\n  }, [page, reloadToken]);\n\n  return (\n    <div className=\"max-w-lg mx-auto mt-8 p-4 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Product Pagination (live API)</h2>\n\n      <div className=\"min-h-70\">\n        {status === \"loading\" && (\n          <div className=\"flex h-70 items-center justify-center text-sm text-gray-400 animate-pulse\">\n            Loading products...\n          </div>\n        )}\n\n        {status === \"error\" && (\n          <div className=\"flex h-70 flex-col items-center justify-center gap-3 text-center\">\n            <p className=\"text-sm text-red-500\">{errorMsg}</p>\n            <button\n              onClick={() => setReloadToken((t) => t + 1)}\n              className=\"px-3 py-1.5 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n            >\n              Retry\n            </button>\n          </div>\n        )}\n\n        {status === \"success\" && (\n          <ul className=\"divide-y divide-gray-100 dark:divide-gray-800\">\n            {products.map((product) => (\n              <li key={product.id} className=\"flex items-center gap-3 py-2 px-1\">\n                <img\n                  src={product.thumbnail}\n                  alt={product.title}\n                  className=\"h-10 w-10 rounded object-cover bg-gray-100\"\n                />\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-medium truncate text-gray-700 dark:text-gray-200\">\n                    {product.title}\n                  </p>\n                  <p className=\"text-xs text-gray-400\">${product.price}</p>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n\n      <div className=\"flex items-center justify-center gap-2 mt-4\">\n        <button\n          disabled={page === 1 || status === \"loading\"}\n          onClick={() => setPage((p) => p - 1)}\n          className=\"px-3 py-1 rounded-md text-sm border border-gray-300 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Prev\n        </button>\n        <span className=\"text-sm text-gray-500\">\n          Page {page} of {totalPages}\n        </span>\n        <button\n          disabled={page === totalPages || status === \"loading\"}\n          onClick={() => setPage((p) => p + 1)}\n          className=\"px-3 py-1 rounded-md text-sm border border-gray-300 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Next\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  SearchFilter: "\"use client\";\nimport { useState } from \"react\";\n\nconst NAMES = [\"Amit\", \"Priya\", \"Rahul\", \"Sneha\", \"Vikram\", \"Anjali\", \"Rohit\", \"Neha\"];\n\nexport default function SearchFilter() {\n  const [query, setQuery] = useState(\"\");\n\n  const filtered = NAMES.filter((name) =>\n    name.toLowerCase().includes(query.toLowerCase())\n  );\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Search Filter</h2>\n\n      <input\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Search name...\"\n        className=\"w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n      />\n\n      <ul className=\"mt-4 divide-y divide-gray-100 dark:divide-gray-800\">\n        {filtered.length === 0 ? (\n          <li className=\"py-6 text-center text-gray-400 text-sm\">\n            No results found\n          </li>\n        ) : (\n          filtered.map((name) => (\n            <li key={name} className=\"py-2 text-sm text-gray-700 dark:text-gray-200\">\n              {name}\n            </li>\n          ))\n        )}\n      </ul>\n    </div>\n  );\n}\n",
  ShoppingCart: "\"use client\";\nimport { useState, useMemo } from \"react\";\n\nconst PRODUCTS = [\n  { id: 1, name: \"Wireless Mouse\", price: 799, emoji: \"🖱️\" },\n  { id: 2, name: \"Mechanical Keyboard\", price: 2999, emoji: \"⌨️\" },\n  { id: 3, name: \"USB-C Hub\", price: 1499, emoji: \"🔌\" },\n  { id: 4, name: \"Laptop Stand\", price: 1199, emoji: \"💻\" },\n];\n\nconst TAX_RATE = 0.18;\n\nexport default function ShoppingCart() {\n  const [cart, setCart] = useState({}); // { [productId]: quantity }\n\n  const addToCart = (id) => {\n    setCart((prev) => ({ ...prev, [id]: (prev[id] || 0) + 1 }));\n  };\n\n  const changeQty = (id, delta) => {\n    setCart((prev) => {\n      const nextQty = (prev[id] || 0) + delta;\n      if (nextQty <= 0) {\n        const { [id]: _removed, ...rest } = prev;\n        return rest;\n      }\n      return { ...prev, [id]: nextQty };\n    });\n  };\n\n  const removeFromCart = (id) => {\n    setCart((prev) => {\n      const { [id]: _removed, ...rest } = prev;\n      return rest;\n    });\n  };\n\n  const cartItems = useMemo(\n    () =>\n      Object.entries(cart)\n        .map(([id, qty]) => ({ ...PRODUCTS.find((p) => p.id === Number(id)), qty }))\n        .filter(Boolean),\n    [cart]\n  );\n\n  const subtotal = useMemo(\n    () => cartItems.reduce((sum, item) => sum + item.price * item.qty, 0),\n    [cartItems]\n  );\n  const tax = Math.round(subtotal * TAX_RATE);\n  const total = subtotal + tax;\n\n  return (\n    <div className=\"max-w-2xl mx-auto mt-8 p-4 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n      <div className=\"rounded-lg border border-gray-200 shadow-sm p-4 dark:border-gray-700\">\n        <h2 className=\"text-lg font-semibold mb-3\">Products</h2>\n        <ul className=\"space-y-2\">\n          {PRODUCTS.map((product) => (\n            <li key={product.id} className=\"flex items-center justify-between gap-2\">\n              <span className=\"text-sm\">\n                {product.emoji} {product.name} — ₹{product.price}\n              </span>\n              <button\n                onClick={() => addToCart(product.id)}\n                className=\"px-2 py-1 rounded-md bg-blue-600 text-white text-xs hover:bg-blue-700\"\n              >\n                Add\n              </button>\n            </li>\n          ))}\n        </ul>\n      </div>\n\n      <div className=\"rounded-lg border border-gray-200 shadow-sm p-4 dark:border-gray-700\">\n        <h2 className=\"text-lg font-semibold mb-3\">Cart</h2>\n\n        {cartItems.length === 0 ? (\n          <p className=\"text-sm text-gray-400 text-center py-6\">Cart is empty</p>\n        ) : (\n          <ul className=\"divide-y divide-gray-100 dark:divide-gray-800\">\n            {cartItems.map((item) => (\n              <li key={item.id} className=\"py-2\">\n                <div className=\"flex items-center justify-between\">\n                  <span className=\"text-sm\">{item.emoji} {item.name}</span>\n                  <button\n                    onClick={() => removeFromCart(item.id)}\n                    className=\"text-xs text-red-500 hover:text-red-700\"\n                  >\n                    Remove\n                  </button>\n                </div>\n                <div className=\"flex items-center justify-between mt-1\">\n                  <div className=\"flex items-center gap-2\">\n                    <button\n                      onClick={() => changeQty(item.id, -1)}\n                      className=\"h-6 w-6 rounded border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n                    >\n                      −\n                    </button>\n                    <span className=\"text-sm w-4 text-center\">{item.qty}</span>\n                    <button\n                      onClick={() => changeQty(item.id, 1)}\n                      className=\"h-6 w-6 rounded border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n                    >\n                      +\n                    </button>\n                  </div>\n                  <span className=\"text-sm text-gray-500\">₹{item.price * item.qty}</span>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n\n        {cartItems.length > 0 && (\n          <div className=\"mt-3 pt-3 border-t border-gray-200 dark:border-gray-700 text-sm space-y-1\">\n            <div className=\"flex justify-between text-gray-500\">\n              <span>Subtotal</span>\n              <span>₹{subtotal}</span>\n            </div>\n            <div className=\"flex justify-between text-gray-500\">\n              <span>Tax (18%)</span>\n              <span>₹{tax}</span>\n            </div>\n            <div className=\"flex justify-between font-semibold\">\n              <span>Total</span>\n              <span>₹{total}</span>\n            </div>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
  StarRating: "\"use client\";\nimport { useState } from \"react\";\n\nexport default function StarRating({ totalStars = 5 }) {\n  const [rating, setRating] = useState(0);\n  const [hover, setHover] = useState(0);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Star Rating</h2>\n\n      <div className=\"flex items-center justify-center gap-1\">\n        {Array.from({ length: totalStars }, (_, i) => i + 1).map((star) => (\n          <button\n            key={star}\n            onClick={() => setRating(star)}\n            onMouseEnter={() => setHover(star)}\n            onMouseLeave={() => setHover(0)}\n            className={`text-3xl leading-none transition-colors ${\n              star <= (hover || rating) ? \"text-yellow-400\" : \"text-gray-300 dark:text-gray-600\"\n            }`}\n          >\n            ★\n          </button>\n        ))}\n      </div>\n\n      <p className=\"mt-3 text-sm text-gray-500 dark:text-gray-400\">\n        Your rating: {rating}\n      </p>\n    </div>\n  );\n}\n",
  Stopwatch: "\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\n\nexport default function Stopwatch() {\n  const [time, setTime] = useState(0);\n  const [running, setRunning] = useState(false);\n  const intervalRef = useRef(null);\n\n  useEffect(() => {\n    if (running) {\n      intervalRef.current = setInterval(() => {\n        setTime((prev) => prev + 1);\n      }, 1000);\n    }\n    return () => clearInterval(intervalRef.current);\n  }, [running]);\n\n  const formatTime = (seconds) => {\n    const mins = String(Math.floor(seconds / 60)).padStart(2, \"0\");\n    const secs = String(seconds % 60).padStart(2, \"0\");\n    return `${mins}:${secs}`;\n  };\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Stopwatch</h2>\n      <p className=\"text-4xl font-bold font-mono mb-6\">{formatTime(time)}</p>\n\n      <div className=\"flex items-center justify-center gap-2\">\n        <button\n          onClick={() => setRunning(true)}\n          className=\"px-3 py-1.5 rounded-md bg-green-600 text-white text-sm hover:bg-green-700\"\n        >\n          Start\n        </button>\n        <button\n          onClick={() => setRunning(false)}\n          className=\"px-3 py-1.5 rounded-md bg-yellow-500 text-white text-sm hover:bg-yellow-600\"\n        >\n          Pause\n        </button>\n        <button\n          onClick={() => {\n            setRunning(false);\n            setTime(0);\n          }}\n          className=\"px-3 py-1.5 rounded-md border border-gray-300 text-sm hover:bg-gray-100 dark:hover:bg-gray-800\"\n        >\n          Reset\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  Tabs: "\"use client\";\nimport { useState } from \"react\";\n\nconst TABS = [\n  { label: \"Home\", content: \"This is the Home tab content.\" },\n  { label: \"Profile\", content: \"This is the Profile tab content.\" },\n  { label: \"Settings\", content: \"This is the Settings tab content.\" },\n];\n\nexport default function Tabs() {\n  const [activeTab, setActiveTab] = useState(0);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Tabs</h2>\n\n      <div className=\"flex border-b border-gray-200 dark:border-gray-700\">\n        {TABS.map((tab, index) => (\n          <button\n            key={tab.label}\n            onClick={() => setActiveTab(index)}\n            className={`px-4 py-2 text-sm -mb-px border-b-2 transition-colors ${\n              activeTab === index\n                ? \"border-blue-600 text-blue-600 font-medium\"\n                : \"border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300\"\n            }`}\n          >\n            {tab.label}\n          </button>\n        ))}\n      </div>\n\n      <p className=\"pt-4 text-sm text-gray-600 dark:text-gray-300\">\n        {TABS[activeTab].content}\n      </p>\n    </div>\n  );\n}\n",
  Toast: "\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\n\nexport default function Toast() {\n  const [toasts, setToasts] = useState([]);\n  const timersRef = useRef([]);\n\n  // clear any pending timers on unmount\n  useEffect(() => {\n    return () => timersRef.current.forEach(clearTimeout);\n  }, []);\n\n  const showToast = (message) => {\n    const id = Date.now();\n    setToasts((prev) => [...prev, { id, message }]);\n\n    const timer = setTimeout(() => {\n      setToasts((prev) => prev.filter((toast) => toast.id !== id));\n    }, 3000);\n    timersRef.current.push(timer);\n  };\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm text-center dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4\">Toast Notification</h2>\n      <button\n        onClick={() => showToast(\"This is a toast message!\")}\n        className=\"px-4 py-2 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n      >\n        Show Toast\n      </button>\n\n      <div className=\"fixed bottom-5 right-5 flex flex-col gap-2 z-50\">\n        {toasts.map((toast) => (\n          <div\n            key={toast.id}\n            className=\"bg-gray-900 text-white text-sm px-4 py-2 rounded-md shadow-lg\"\n          >\n            {toast.message}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
  Todo: "\"use client\";\nimport { useState, useEffect, useCallback, memo } from \"react\";\n\n// Extracted + memoized so toggling/deleting one task doesn't re-render every other <TodoItem>.\n// Without React.memo here, every setTasks() call in the parent would re-render the entire list.\nconst TodoItem = memo(function TodoItem({ task, onToggle, onDelete }) {\n  return (\n    <li className=\"flex items-center gap-2 py-2\">\n      <span\n        onClick={() => onToggle(task.id)}\n        className={`flex-1 cursor-pointer text-sm ${\n          task.done ? \"line-through text-gray-400\" : \"text-gray-700 dark:text-gray-200\"\n        }`}\n      >\n        {task.text}\n      </span>\n      <button\n        onClick={() => onDelete(task.id)}\n        className=\"text-xs text-red-500 hover:text-red-700\"\n      >\n        Delete\n      </button>\n    </li>\n  );\n});\n\nexport default function Todo() {\n  const [tasks, setTasks] = useState([]);\n  const [input, setInput] = useState(\"\");\n\n  // load saved tasks once on mount\n  useEffect(() => {\n    const saved = localStorage.getItem(\"todo-tasks\");\n    if (saved) setTasks(JSON.parse(saved));\n  }, []);\n\n  // persist tasks whenever they change\n  useEffect(() => {\n    localStorage.setItem(\"todo-tasks\", JSON.stringify(tasks));\n  }, [tasks]);\n\n  const addTask = useCallback(() => {\n    setInput((currentInput) => {\n      if (!currentInput.trim()) return currentInput;\n      setTasks((prev) => [...prev, { id: Date.now(), text: currentInput, done: false }]);\n      return \"\";\n    });\n  }, []);\n\n  const toggleTask = useCallback((id) => {\n    setTasks((prev) =>\n      prev.map((task) => (task.id === id ? { ...task, done: !task.done } : task))\n    );\n  }, []);\n\n  const deleteTask = useCallback((id) => {\n    setTasks((prev) => prev.filter((task) => task.id !== id));\n  }, []);\n\n  return (\n    <div className=\"max-w-sm mx-auto mt-8 p-6 rounded-lg border border-gray-200 shadow-sm dark:border-gray-700\">\n      <h2 className=\"text-xl font-semibold mb-4 text-center\">Todo List</h2>\n\n      <div className=\"flex gap-2\">\n        <input\n          value={input}\n          onChange={(e) => setInput(e.target.value)}\n          onKeyDown={(e) => e.key === \"Enter\" && addTask()}\n          placeholder=\"Add a task\"\n          className=\"flex-1 rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-transparent\"\n        />\n        <button\n          onClick={addTask}\n          className=\"px-3 py-1.5 rounded-md bg-blue-600 text-white text-sm hover:bg-blue-700\"\n        >\n          Add\n        </button>\n      </div>\n\n      <ul className=\"mt-4 divide-y divide-gray-100 dark:divide-gray-800\">\n        {tasks.length === 0 && (\n          <li className=\"py-6 text-center text-gray-400 text-sm\">\n            No tasks yet\n          </li>\n        )}\n        {tasks.map((task) => (\n          <TodoItem key={task.id} task={task} onToggle={toggleTask} onDelete={deleteTask} />\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
};
